def poser(chapitres: list, textes: dict) -> None:
    """Ajoute les chapitres neufs à la fin de CHAPITRES (ancres existantes inchangées) et leurs textes."""
    for cid in NOUVEAUX:
        if not any(c["id"] == cid for c in chapitres):
            chapitres.append({"id": cid, "schemas": [], "regles": []})
        for lang, t in textes.items():
            t["ch"][cid] = TEXTES_NEUFS[cid][lang]
